package com.anthony6996.hardcorecompass.command;
import com.anthony6996.hardcorecompass.HardcoreCompassPlugin;import com.anthony6996.hardcorecompass.config.ConfigManager;import com.anthony6996.hardcorecompass.manager.*;import org.bukkit.Bukkit;import org.bukkit.command.*;import org.bukkit.entity.Player;import java.util.*;
public final class CompassCommand implements CommandExecutor,TabCompleter{private final HardcoreCompassPlugin plugin;private final LivesManager lives;private final ConfigManager config;private final CompassManager compasses;public CompassCommand(HardcoreCompassPlugin p,LivesManager l,ConfigManager c,CompassManager m){plugin=p;lives=l;config=c;compasses=m;}private String msg(CommandSender s,String k){return config.localized(s instanceof Player p?config.language(p):config.defaultLanguage(),k);}private boolean admin(CommandSender s){return s.hasPermission("hardcorecompass.admin");}@Override public boolean onCommand(CommandSender s,Command c,String label,String[] a){if(a.length==0||a[0].equalsIgnoreCase("help")){s.sendMessage(msg(s,admin(s)?"help-admin":"help-player"));return true;}String sub=a[0].toLowerCase(Locale.ROOT);if(!admin(s)&&Set.of("give","reset","radius","reload","setpreserve","wipelinks").contains(sub)){s.sendMessage(msg(s,"no-permission"));return true;}if(sub.equals("setpreserve")){if(a.length!=2||(!a[1].equalsIgnoreCase("true")&&!a[1].equalsIgnoreCase("false"))){s.sendMessage(msg(s,"preserve-usage"));return true;}config.setPreserveOnFirstDeath(Boolean.parseBoolean(a[1]));s.sendMessage(msg(s,"preserve-set").replace("{value}",a[1]));return true;}if(sub.equals("reset")){if(a.length!=3||!a[2].equalsIgnoreCase("deaths")){s.sendMessage(msg(s,"reset-usage"));return true;}Player t=Bukkit.getPlayerExact(a[1]);if(t==null){s.sendMessage(msg(s,"player-not-found"));return true;}lives.resetDeaths(t.getUniqueId());s.sendMessage(msg(s,"reset-deaths").replace("{player}",t.getName()));return true;}if(sub.equals("wipelinks")){if(a.length!=2){s.sendMessage(msg(s,"wipelinks-usage"));return true;}Player t=Bukkit.getPlayerExact(a[1]);if(t==null){s.sendMessage(msg(s,"player-not-found"));return true;}compasses.wipeLinks(t);s.sendMessage(msg(s,"wipelinks-done").replace("{player}",t.getName()));return true;}if(sub.equals("radius")&&a.length==3){try{int min=Integer.parseInt(a[1]),max=Integer.parseInt(a[2]);if(min<0||max<min)throw new NumberFormatException();config.setRadius(min,max);s.sendMessage(msg(s,"radius-set").replace("{min}",a[1]).replace("{max}",a[2]));}catch(NumberFormatException ex){s.sendMessage(msg(s,"radius-usage"));}return true;}if(sub.equals("reload")){plugin.reloadPluginConfig();s.sendMessage(msg(s,"reloaded"));return true;}s.sendMessage(msg(s,admin(s)?"help-admin":"help-player"));return true;}@Override public List<String> onTabComplete(CommandSender s,Command c,String a,String[] args){if(args.length==1)return List.of("help","setpreserve","reset","wipelinks","radius","reload").stream().filter(x->x.startsWith(args[0].toLowerCase(Locale.ROOT))).toList();return List.of();}}
